SELECT COALESCE(MAX(result_version), 0)
FROM cut_cutover_checklist_item_result
WHERE tenant_id = #{query.tenantId}
  AND checklist_item_id = #{query.checklistItemId}
  AND deleted = b'0'

mapper.update:
UPDATE cut_cutover_checklist_item_result
SET selection_end_time = #{query.endedAt}
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.resultId}
  AND selection_end_time IS NULL
  AND deleted = b'0'
